func bubbleSort(nums: inout [Int]) {
    // 外循环：未排序区间为 [0, i]
    for i in nums.indices.dropFirst().reversed() {
        // 内循环：将未排序区间 [0, i] 中的最大元素交换至该区间的最右端
        for j in 0 ..< i {
            if nums[j] > nums[j + 1] {
                // 交换 nums[j] 与 nums[j + 1]
                nums.swapAt(j, j + 1)
            }
        }
    }
}

